import "core-js/modules/es6.string.link";
import "core-js/modules/es6.regexp.split";
import { getList, getDept, feedbackSave, feedbackUpdate, feedbackDetail, feedbackAccept, feedbackFinish, feedbackLoad } from "@/api/userFeedback/index.js";
import { add, update } from "@/api/operation/safeaccess/areacode";
import uploadImg from "./uploadImg.vue";
import { Message } from "element-ui";
import { getDictList as _getDictList } from '@/api/dict';
export default {
  props: ['isShow', 'arrtId', 'type', 'detailId'],
  components: {
    uploadImg: uploadImg
  },
  data: function data() {
    return {
      deptList: [],
      formDetial: {
        isFinish: "",
        backType: ""
      },
      isView: false,
      fileList: [
        // {
        //   url: "http://xt-public-storage.oss-cn-jinan-sddlyf-d01-a.ops-devcloud.sd.sgcc.com.cn/upload/20250327/c018f202546bd257905e8a5342e4e202.png"
        // }
      ],
      isAcceptOptions: [],
      isFinishOptions: [{
        dictKey: '1',
        dictValue: '是'
      }, {
        dictKey: '0',
        dictValue: '否'
      }],
      backTypeOptions: [],
      saveLoading: false,
      typeList: null,
      rules: {
        backNum: [{
          required: true,
          message: '反馈编号不能为空',
          trigger: 'blur'
        }],
        dept: [{
          required: true,
          message: '反馈单位不能为空',
          trigger: 'change'
        }],
        userName: [{
          required: true,
          message: '反馈人员不能为空',
          trigger: 'blur'
        }],
        createTime: [{
          required: true,
          message: '创建时间不能为空',
          trigger: 'change'
        }],
        phone: [{
          required: true,
          message: '联系方式不能为空',
          trigger: 'blur'
        }],
        backDetail: [{
          required: true,
          message: '问题描述不能为空',
          trigger: 'blur'
        }],
        backType: [{
          required: true,
          message: '问题类型不能为空',
          trigger: 'change'
        }],
        backBriefly: [{
          required: true,
          message: '问题简介不能为空',
          trigger: 'blur'
        }],
        img: [{
          required: true,
          message: '上传图片不能为空',
          trigger: 'change'
        }],
        isAccept: [{
          required: true,
          message: '是否采纳不能为空',
          trigger: 'change'
        }],
        expectedTime: [{
          required: true,
          message: '预计完成时间不能为空',
          trigger: 'change'
        }],
        noAcceptDetail: [{
          required: true,
          message: '未采纳原因不能为空',
          trigger: 'blur'
        }],
        isFinish: [{
          required: true,
          message: '是否完成不能为空',
          trigger: 'change'
        }]
        // remark: [{required: true, message: '备注不能为空', trigger: 'blur'}],
      }
    };
  },
  computed: {},
  mounted: function mounted() {
    var _this = this;
    this.getDeptList();
    this.getDictList('back_isAccept');
    this.getDictList('back_type');
    if (this.type == 'add') {
      feedbackLoad().then(function (res) {
        _this.formDetial = res.data;
      });
    }
    if (this.type != 'add') {
      feedbackDetail({
        id: this.detailId
      }).then(function (res) {
        _this.formDetial = res.data;
        if (res.data.img) {
          var urlArr = res.data.img.split(',');
          _this.fileList = urlArr.map(function (ele) {
            return {
              url: ele
            };
          });
        }
      });
    }
  },
  watch: {
    'formDetial.isAccept': {
      // deep: true,
      handler: function handler(val, oldVal) {
        // console.log(val)
        if (val == 1) {
          // 已采纳
          this.rules.noAcceptDetail = [{
            required: false,
            message: '未采纳原因不能为空',
            trigger: 'blur'
          }];
          this.$refs.submitForm.validateField('noAcceptDetail');
        } else {
          // 未采纳
          this.rules.noAcceptDetail = [{
            required: true,
            message: '未采纳原因不能为空',
            trigger: 'blur'
          }];
        }
      }
    }
  },
  methods: {
    isAcceptChange: function isAcceptChange(val) {
      // console.log(val)
      // if(val == 1){ // 已采纳
      //   this.rules.noAcceptDetail = [{required: false, message: '未采纳原因不能为空', trigger: 'blur'}]
      //   this.$refs.submitForm.validateField('noAcceptDetail')
      // }else{ // 未采纳
      //   this.rules.noAcceptDetail = [{required: true, message: '未采纳原因不能为空', trigger: 'blur'}]
      // }
    },
    deptChange: function deptChange(val) {
      var current = this.deptList.filter(function (ele) {
        return ele.id == val;
      })[0];
      this.formDetial.deptName = current.fullName;
    },
    getDictList: function getDictList(code) {
      var _this2 = this;
      //加载字典
      _getDictList(code).then(function (res) {
        if (code === 'back_isAccept') {
          _this2.isAcceptOptions = res.data;
        } else if (code === 'back_type') {
          _this2.backTypeOptions = res.data;
        }
      });
    },
    selectDeviceFileHandler: function selectDeviceFileHandler(file123, fileList) {
      //新增文件
      // this.form.orderFile = undefined
      // if(file123){
      //   this.form.orderFile = file123
      // }
      // console.log(111, file123, fileList)

      var arr = fileList.map(function (ele) {
        if (ele.response) {
          return ele.response.data.link;
        } else {
          return ele.url;
        }
      });
      this.formDetial.img = arr.join(',');
      this.$refs.submitForm.validateField('img');
    },
    getDeptList: function getDeptList() {
      var _this3 = this;
      getDept({}).then(function (res) {
        _this3.deptList = res.data;
      });
    },
    selectionChange: function selectionChange(val) {
      this.selectionList = val;
    },
    submit: function submit() {
      var _this4 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          if (_this4.type == 'add') {
            _this4.saveLoading = true;
            feedbackSave(_this4.formDetial).then(function (res) {
              _this4.saveLoading = false;
              _this4.$message.success('添加成功');
              _this4.$emit("close");
              _this4.$emit("refreshData");
            });
          } else if (_this4.type == 'edit') {
            _this4.saveLoading = true;
            feedbackUpdate(_this4.formDetial).then(function (res) {
              _this4.saveLoading = false;
              _this4.$message.success('修改成功');
              _this4.$emit("close");
              _this4.$emit("refreshData");
            });
          } else if (_this4.type == 'adopt') {
            _this4.saveLoading = true;
            feedbackAccept(_this4.formDetial).then(function (res) {
              _this4.saveLoading = false;
              _this4.$message.success('操作成功');
              _this4.$emit("close");
              _this4.$emit("refreshData");
            });
          } else if (_this4.type == 'finshed') {
            _this4.saveLoading = true;
            feedbackFinish(_this4.formDetial).then(function (res) {
              _this4.saveLoading = false;
              _this4.$message.success('操作成功');
              _this4.$emit("close");
              _this4.$emit("refreshData");
            });
          }
        }
      });
    },
    getTitle: function getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      } else if (type == 'check') {
        return '查 看';
      } else if (type == 'adopt') {
        return '采 纳';
      } else if (type == 'finshed') {
        return '完 成';
      }
      return null;
    }
  }
};
